package com.prayerhoversounds;

import net.runelite.client.util.Text;

/**
 * Which prayer the mouse is on, from the menu's left-click entry ("Activate" / "Deactivate" "Piety" in the prayer book),
 * and when it has just moved onto one: one sound per move onto a prayer, none while it stays there. Every prayer is
 * tracked by its name, so moving from one prayer straight onto another counts as a move; which names make a sound is
 * the settings' business ({@link PrayerHoverSoundsPlugin#toneFor}). Pure logic, tested offline (HoverTrackerTest).
 * Client thread.
 */
final class HoverTracker
{
	private String last;

	/**
	 * The menu's left-click entry now ({@code inPrayerBook}: it belongs to the prayer book). Returns the name of the
	 * prayer the mouse has just moved onto ("Protect from Magic", "Piety"), else null.
	 */
	String update(boolean inPrayerBook, String target)
	{
		String now = inPrayerBook ? nameOf(target) : null;
		String entered = now != null && !now.equals(last) ? now : null;
		last = now;
		return entered;
	}

	/** The prayer a menu target names ("<col=ff9040>Protect from Melee</col>" → "Protect from Melee"), else null. */
	static String nameOf(String target)
	{
		String t = target == null ? "" : Text.removeTags(target).trim();
		return t.isEmpty() ? null : t;
	}
}

