@ConfigGroup(PrayerHoverSoundsConfig.GROUP)
public interface PrayerHoverSoundsConfig extends Config
{
	String GROUP = "prayerhoversounds";

	/**
	 * A short sound bundled with the plugin; each starts at once. The beeps, chimes, two-note sounds and the sword slash, arrow
	 * shot and magic blast were made for the plugin; the recorded ones (sword swings to force fields) are CC0 sound effects from OpenGameArt, cut to start at
	 * once (see the README). The game's own attack sounds were tried and dropped (user: "too much silence time before
	 * the sound starts") — they wait 150-510 ms, timed to the attack animation.
	 */
	enum Tone
	{
		HIGH("High beep", "high.wav"),
		MID("Middle beep", "mid.wav"),
		LOW("Low beep", "low.wav"),
		CHIME_HIGH("High chime", "chime_high.wav"),
		CHIME_MID("Middle chime", "chime_mid.wav"),
		CHIME_LOW("Low chime", "chime_low.wav"),
		RISING("Rising two notes", "rising.wav"),
		FALLING("Falling two notes", "falling.wav"),
		DOUBLE("Double beep", "double.wav"),
		CLICK("Click", "click.wav"),
		SWORD("Sword slash", "sword.wav"),
		ARROW("Arrow shot", "arrow.wav"),
		MAGIC("Magic blast", "magic.wav"),
		KATANA_SWING("Katana swing", "katana_swing.wav"),
		SWING_1("Swing 1", "swing_1.wav"),
		SWING_2("Swing 2", "swing_2.wav"),
		SWING_3("Swing 3", "swing_3.wav"),
		SWISH_1("Swish 1", "swish_1.wav"),
		SWISH_2("Swish 2", "swish_2.wav"),
		SWISH_3("Swish 3", "swish_3.wav"),
		SWORD_UNSHEATHE("Sword unsheathe", "sword_unsheathe.wav"),
		METAL_RING("Metal ring", "metal_ring.wav"),
		COIN_FLIP("Coin flip", "coin_flip.wav"),
		MATCH_STRIKE("Match strike", "match_strike.wav"),
		LONGBOW_SHOT("Longbow shot", "longbow_shot.wav"),
		CROSSBOW_SHOT("Crossbow shot", "crossbow_shot.wav"),
		FORCE_FIELD_1("Force field 1", "force_field_1.wav"),
		FORCE_FIELD_2("Force field 2", "force_field_2.wav"),
		FORCE_FIELD_3("Force field 3", "force_field_3.wav"),
		FORCE_FIELD_4("Force field 4", "force_field_4.wav"),
		FORCE_FIELD_5("Force field 5", "force_field_5.wav"),
		NONE("No sound", null);

		private final String label;
		final String file;

		Tone(String label, String file)
		{
			this.label = label;
			this.file = file;
		}

		@Override
		public String toString()
		{
			return label;
		}
	}

	/** The offensive prayers a slot can name, by their names in the prayer book; melee, then ranged, then magic. */
	enum OffensivePrayer
	{
		NONE(null),
		PIETY("Piety"),
		CHIVALRY("Chivalry"),
		ULTIMATE_STRENGTH("Ultimate Strength"),
		INCREDIBLE_REFLEXES("Incredible Reflexes"),
		SUPERHUMAN_STRENGTH("Superhuman Strength"),
		IMPROVED_REFLEXES("Improved Reflexes"),
		BURST_OF_STRENGTH("Burst of Strength"),
		CLARITY_OF_THOUGHT("Clarity of Thought"),
		RIGOUR("Rigour"),
		DEADEYE("Deadeye"),
		EAGLE_EYE("Eagle Eye"),
		HAWK_EYE("Hawk Eye"),
		SHARP_EYE("Sharp Eye"),
		AUGURY("Augury"),
		MYSTIC_VIGOUR("Mystic Vigour"),
		MYSTIC_MIGHT("Mystic Might"),
		MYSTIC_LORE("Mystic Lore"),
		MYSTIC_WILL("Mystic Will");

		/** The name in the prayer book; null for NONE. */
		final String name;

		OffensivePrayer(String name)
		{
			this.name = name;
		}

		@Override
		public String toString()
		{
			return name == null ? "None" : name;
		}
	}

	@ConfigSection(
		position = 1,
		name = "Protection prayers",
		description = "The sound for each protection prayer"
	)
	String protectionSection = "protection";

	@ConfigSection(
		position = 2,
		name = "Offensive prayers",
		description = "Up to four offensive prayers that make a sound too, each with its own sound"
	)
	String offensiveSection = "offensive";

	@ConfigSection(
		position = 3,
		name = "Test sounds",
		description = "Hear any sound before you pick it"
	)
	String testSection = "test";

	@Range(min = 0, max = 100)
	@ConfigItem(
		position = 0,
		keyName = "volume",
		name = "Volume",
		description = "How loud the sounds are, 0-100. They play even with the game's sound effects turned off"
	)
	default int volume()
	{
		return 50;
	}

	@ConfigItem(
		position = 0,
		keyName = "protectionOn",
		name = "Protection prayer sounds",
		description = "Off: Protect from Magic, Missiles and Melee make no sound (the offensive prayers still do)",
		section = protectionSection
	)
	default boolean protectionOn()
	{
		return true;
	}

	@ConfigItem(
		position = 1,
		keyName = "magicTone",
		name = "Protect from Magic",
		description = "The sound when your mouse moves onto Protect from Magic",
		section = protectionSection
	)
	default Tone magicTone()
	{
		return Tone.FORCE_FIELD_5;
	}

	@ConfigItem(
		position = 2,
		keyName = "missilesTone",
		name = "Protect from Missiles",
		description = "The sound when your mouse moves onto Protect from Missiles",
		section = protectionSection
	)
	default Tone missilesTone()
	{
		return Tone.LONGBOW_SHOT;
	}

	@ConfigItem(
		position = 3,
		keyName = "meleeTone",
		name = "Protect from Melee",
		description = "The sound when your mouse moves onto Protect from Melee",
		section = protectionSection
	)
	default Tone meleeTone()
	{
		return Tone.SWORD_UNSHEATHE;
	}

	@ConfigItem(
		position = 0,
		keyName = "offensive1",
		name = "Prayer 1",
		description = "An offensive prayer that plays a sound when your mouse moves onto it. None = no prayer here",
		section = offensiveSection
	)
	default OffensivePrayer offensive1()
	{
		return OffensivePrayer.PIETY;
	}

	@ConfigItem(
		position = 1,
		keyName = "offensive1Tone",
		name = "Prayer 1 sound",
		description = "The sound for prayer 1",
		section = offensiveSection
	)
	default Tone offensive1Tone()
	{
		return Tone.SWISH_2;
	}

	@ConfigItem(
		position = 2,
		keyName = "offensive2",
		name = "Prayer 2",
		description = "An offensive prayer that plays a sound when your mouse moves onto it. None = no prayer here",
		section = offensiveSection
	)
	default OffensivePrayer offensive2()
	{
		return OffensivePrayer.RIGOUR;
	}

	@ConfigItem(
		position = 3,
		keyName = "offensive2Tone",
		name = "Prayer 2 sound",
		description = "The sound for prayer 2",
		section = offensiveSection
	)
	default Tone offensive2Tone()
	{
		return Tone.CROSSBOW_SHOT;
	}

	@ConfigItem(
		position = 4,
		keyName = "offensive3",
		name = "Prayer 3",
		description = "An offensive prayer that plays a sound when your mouse moves onto it. None = no prayer here",
		section = offensiveSection
	)
	default OffensivePrayer offensive3()
	{
		return OffensivePrayer.AUGURY;
	}

	@ConfigItem(
		position = 5,
		keyName = "offensive3Tone",
		name = "Prayer 3 sound",
		description = "The sound for prayer 3",
		section = offensiveSection
	)
	default Tone offensive3Tone()
	{
		return Tone.FORCE_FIELD_2;
	}

	@ConfigItem(
		position = 6,
		keyName = "offensive4",
		name = "Prayer 4",
		description = "A fourth offensive prayer that plays a sound when your mouse moves onto it. None (the default) "
			+ "= this slot is off",
		section = offensiveSection
	)
	default OffensivePrayer offensive4()
	{
		return OffensivePrayer.NONE;
	}

	@ConfigItem(
		position = 7,
		keyName = "offensive4Tone",
		name = "Prayer 4 sound",
		description = "The sound for prayer 4",
		section = offensiveSection
	)
	default Tone offensive4Tone()
	{
		return Tone.CHIME_MID;
	}

	@ConfigItem(
		position = 0,
		keyName = "testSound",
		name = "Sound",
		description = "Any of the sounds. Picking one plays it (pick another and back to hear it again)",
		section = testSection
	)
	default Tone testSound()
	{
		return Tone.KATANA_SWING;
	}
}

