package com.prayerhoversounds;

import com.google.inject.Provides;
import java.io.IOException;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import javax.sound.sampled.LineUnavailableException;
import javax.sound.sampled.UnsupportedAudioFileException;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.ClientTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Plays a different sound when the mouse moves onto Protect from Magic, Missiles or Melee in the prayer book — and onto
 * up to four offensive prayers the player picks — so the player knows which one they are on without looking. It only
 * plays a sound: no click, no menu change, nothing about the prayers themselves.
 */
@PluginDescriptor(
	name = "Prayer Hover Sounds",
	description = "A different sound when your mouse moves onto a protection prayer, or an offensive prayer you pick",
	tags = {"prayer", "protect", "protection", "offensive", "piety", "rigour", "augury", "sound", "audio", "hover",
		"accessibility"}
)
public class PrayerHoverSoundsPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(PrayerHoverSoundsPlugin.class);

	@Inject
	private Client client;
	@Inject
	private PrayerHoverSoundsConfig config;
	@Inject
	private AudioPlayer audioPlayer;
	@Inject
	private ScheduledExecutorService executor;

	private static final String PROTECT_MAGIC = "Protect from Magic";
	private static final String PROTECT_MISSILES = "Protect from Missiles";
	private static final String PROTECT_MELEE = "Protect from Melee";

	/** The settings that choose a sound: changing one plays the new choice, so the player hears what they picked. */
	static final Set<String> SOUND_KEYS = Set.of("magicTone", "missilesTone", "meleeTone", "offensive1Tone",
		"offensive2Tone", "offensive3Tone", "offensive4Tone", "testSound");
	/** One preview at most this often: a profile switch or "Reset" changes many settings at once — one sound, not a burst. */
	private static final long PREVIEW_GAP_MS = 300;

	private final HoverTracker tracker = new HoverTracker();
	private long lastPreviewMs;

	@Provides
	PrayerHoverSoundsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(PrayerHoverSoundsConfig.class);
	}

	/**
	 * Java's sound system is started now, with a silent sound (50 ms of zeros, made for the plugin), so the first hover
	 * of a session is not late: the first sound of a run took 165 ms to start, the ones after ~21 ms (measured
	 * 2026-11-03 with RuneLite's AudioPlayer).
	 */
	@Override
	protected void startUp()
	{
		executor.execute(() ->
		{
			try
			{
				audioPlayer.play(PrayerHoverSoundsPlugin.class, "silence.wav", 0f);
			}
			catch (IOException | UnsupportedAudioFileException | LineUnavailableException ex)
			{
				log.debug("Prayer Hover Sounds: could not warm the sound system up", ex);
			}
		});
	}

	/** Every client tick (20 ms): what the left click would do now — a prayer just moved onto plays its sound. */
	@Subscribe
	public void onClientTick(ClientTick e)
	{
		MenuEntry[] entries = client.getMenu().getMenuEntries();
		MenuEntry top = client.isMenuOpen() || entries.length == 0 ? null : entries[entries.length - 1];
		boolean prayerBook = top != null && WidgetUtil.componentToInterface(top.getParam1()) == InterfaceID.PRAYERBOOK;
		String prayer = tracker.update(prayerBook, top == null ? null : top.getTarget());
		if (prayer != null)
		{
			play(toneFor(prayer, config));
		}
	}

	/** The settings panel: a sound just chosen plays, so the player hears what they picked. */
	@Subscribe
	public void onConfigChanged(ConfigChanged e)
	{
		if (!PrayerHoverSoundsConfig.GROUP.equals(e.getGroup()) || e.getKey() == null || e.getNewValue() == null)
		{
			return;
		}
		PrayerHoverSoundsConfig.Tone preview = SOUND_KEYS.contains(e.getKey()) ? toneNamed(e.getNewValue()) : null;
		long now = System.currentTimeMillis();
		if (preview != null && now - lastPreviewMs >= PREVIEW_GAP_MS)
		{
			lastPreviewMs = now;
			play(preview);
		}
	}

	/** A stored sound setting ("KATANA_SWING") back to its sound, or null. */
	static PrayerHoverSoundsConfig.Tone toneNamed(String stored)
	{
		for (PrayerHoverSoundsConfig.Tone t : PrayerHoverSoundsConfig.Tone.values())
		{
			if (t.name().equals(stored))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * The sound for a prayer, by its name in the prayer book: the three protection prayers (while "Protection prayer
	 * sounds" is on), then the offensive prayers picked in the settings (the first slot that names it). Null: this
	 * prayer makes no sound.
	 */
	static PrayerHoverSoundsConfig.Tone toneFor(String prayer, PrayerHoverSoundsConfig c)
	{
		if (PROTECT_MAGIC.equalsIgnoreCase(prayer))
		{
			return c.protectionOn() ? c.magicTone() : null;
		}
		if (PROTECT_MISSILES.equalsIgnoreCase(prayer))
		{
			return c.protectionOn() ? c.missilesTone() : null;
		}
		if (PROTECT_MELEE.equalsIgnoreCase(prayer))
		{
			return c.protectionOn() ? c.meleeTone() : null;
		}
		PrayerHoverSoundsConfig.OffensivePrayer[] slots = {c.offensive1(), c.offensive2(), c.offensive3(), c.offensive4()};
		PrayerHoverSoundsConfig.Tone[] tones = {c.offensive1Tone(), c.offensive2Tone(), c.offensive3Tone(),
			c.offensive4Tone()};
		for (int i = 0; i < slots.length; i++)
		{
			if (slots[i] != null && slots[i].name != null && slots[i].name.equalsIgnoreCase(prayer))
			{
				return tones[i];
			}
		}
		return null;
	}

	private void play(PrayerHoverSoundsConfig.Tone tone)
	{
		int volume = config.volume();
		if (tone == null || tone.file == null || volume <= 0)
		{
			return;
		}
		float gain = (float) (20 * Math.log10(volume / 100.0));      // decibels: 100 = as recorded
		// off the client thread: the sound is read from the plugin's jar
		executor.execute(() ->
		{
			try
			{
				audioPlayer.play(PrayerHoverSoundsPlugin.class, tone.file, gain);
			}
			catch (IOException | UnsupportedAudioFileException | LineUnavailableException ex)
			{
				log.debug("Prayer Hover Sounds: could not play {}", tone.file, ex);
			}
		});
	}
}

