package com.prayerhoversounds;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Offline: one sound per move onto a prayer — none while the mouse stays, none outside the prayer book — and which
 * sound each prayer gets from the settings.
 */
public class HoverTrackerTest
{
	private static final String MAGIC = "<col=ff9040>Protect from Magic</col>";
	private static final String MISSILES = "<col=ff9040>Protect from Missiles</col>";
	private static final String MELEE = "<col=ff9040>Protect from Melee</col>";
	private static final String PIETY = "<col=ff9040>Piety</col>";

	@Test
	public void onceOnEachMoveOntoAPrayer()
	{
		HoverTracker t = new HoverTracker();
		assertEquals("Protect from Magic", t.update(true, MAGIC));
		assertNull(t.update(true, MAGIC));                                   // still on it: no repeat
		assertEquals("Protect from Missiles", t.update(true, MISSILES));
		assertEquals("Protect from Melee", t.update(true, MELEE));
		assertEquals("Piety", t.update(true, PIETY));                       // straight onto another prayer: a move
		assertEquals("Protect from Melee", t.update(true, MELEE));           // back onto it: again
		assertNull(t.update(false, null));                                   // off the prayer book
		assertEquals("Protect from Melee", t.update(true, MELEE));
	}

	@Test
	public void onlyInThePrayerBook()
	{
		HoverTracker t = new HoverTracker();
		assertNull(t.update(false, MAGIC));                                  // the same words elsewhere: nothing
		assertEquals("Protect from Magic", HoverTracker.nameOf("Protect from Magic"));
		assertNull(HoverTracker.nameOf(""));
		assertNull(HoverTracker.nameOf(null));
	}

	@Test
	public void soundsFromTheSettings()
	{
		PrayerHoverSoundsConfig defaults = new PrayerHoverSoundsConfig()
		{
		};
		// the user's own settings are the defaults (screenshot, 2026-11-02)
		assertEquals(PrayerHoverSoundsConfig.Tone.FORCE_FIELD_5,
			PrayerHoverSoundsPlugin.toneFor("Protect from Magic", defaults));
		assertEquals(PrayerHoverSoundsConfig.Tone.LONGBOW_SHOT,
			PrayerHoverSoundsPlugin.toneFor("protect from missiles", defaults));
		assertEquals(PrayerHoverSoundsConfig.Tone.SWORD_UNSHEATHE,
			PrayerHoverSoundsPlugin.toneFor("Protect from Melee", defaults));
		assertEquals(50, defaults.volume());
		// the offensive defaults: Piety a swish, Rigour a crossbow shot, Augury a force field
		assertEquals(PrayerHoverSoundsConfig.Tone.SWISH_2, PrayerHoverSoundsPlugin.toneFor("Piety", defaults));
		assertEquals(PrayerHoverSoundsConfig.Tone.CROSSBOW_SHOT, PrayerHoverSoundsPlugin.toneFor("Rigour", defaults));
		assertEquals(PrayerHoverSoundsConfig.Tone.FORCE_FIELD_2, PrayerHoverSoundsPlugin.toneFor("Augury", defaults));
		assertNull(PrayerHoverSoundsPlugin.toneFor("Eagle Eye", defaults));            // not picked: silent
		assertEquals(PrayerHoverSoundsConfig.OffensivePrayer.NONE, defaults.offensive4());  // slot 4 starts off
		assertNull(PrayerHoverSoundsPlugin.toneFor("Smite", defaults));

		PrayerHoverSoundsConfig picked = new PrayerHoverSoundsConfig()
		{
			@Override
			public OffensivePrayer offensive1()
			{
				return OffensivePrayer.EAGLE_EYE;
			}

			@Override
			public Tone offensive1Tone()
			{
				return Tone.RISING;
			}

			@Override
			public OffensivePrayer offensive2()
			{
				return OffensivePrayer.NONE;
			}

			@Override
			public OffensivePrayer offensive4()
			{
				return OffensivePrayer.MYSTIC_MIGHT;
			}

			@Override
			public Tone offensive4Tone()
			{
				return Tone.FORCE_FIELD_3;
			}
		};
		assertEquals(PrayerHoverSoundsConfig.Tone.RISING, PrayerHoverSoundsPlugin.toneFor("Eagle Eye", picked));
		assertNull(PrayerHoverSoundsPlugin.toneFor("Piety", picked));                   // slot 1 changed away
		assertNull(PrayerHoverSoundsPlugin.toneFor("Rigour", picked));                  // slot 2 set to None
		assertEquals(PrayerHoverSoundsConfig.Tone.FORCE_FIELD_2, PrayerHoverSoundsPlugin.toneFor("Augury", picked));
		assertEquals(PrayerHoverSoundsConfig.Tone.FORCE_FIELD_3, PrayerHoverSoundsPlugin.toneFor("Mystic Might", picked));
	}

	@Test
	public void protectionSoundsCanBeTurnedOff()
	{
		PrayerHoverSoundsConfig off = new PrayerHoverSoundsConfig()
		{
			@Override
			public boolean protectionOn()
			{
				return false;
			}
		};
		assertTrue(new PrayerHoverSoundsConfig()
		{
		}.protectionOn());                                                        // on by default
		assertNull(PrayerHoverSoundsPlugin.toneFor("Protect from Magic", off));
		assertNull(PrayerHoverSoundsPlugin.toneFor("Protect from Missiles", off));
		assertNull(PrayerHoverSoundsPlugin.toneFor("Protect from Melee", off));
		assertEquals(PrayerHoverSoundsConfig.Tone.SWISH_2, PrayerHoverSoundsPlugin.toneFor("Piety", off));
	}

	@Test
	public void testSoundsSettings()
	{
		// every sound setting previews; a stored name maps back to its sound
		for (String k : new String[]{"magicTone", "missilesTone", "meleeTone", "offensive1Tone", "offensive2Tone",
			"offensive3Tone", "offensive4Tone", "testSound"})
		{
			assertTrue(k, PrayerHoverSoundsPlugin.SOUND_KEYS.contains(k));
		}
		assertEquals(8, PrayerHoverSoundsPlugin.SOUND_KEYS.size());
		assertEquals(PrayerHoverSoundsConfig.Tone.LONGBOW_SHOT, PrayerHoverSoundsPlugin.toneNamed("LONGBOW_SHOT"));
		assertNull(PrayerHoverSoundsPlugin.toneNamed("NOT_A_SOUND"));
	}

	@Test
	public void theWarmUpSoundIsSilent() throws Exception
	{
		try (javax.sound.sampled.AudioInputStream in = javax.sound.sampled.AudioSystem.getAudioInputStream(
			new java.io.BufferedInputStream(PrayerHoverSoundsPlugin.class.getResourceAsStream("silence.wav"))))
		{
			byte[] all = in.readAllBytes();
			assertTrue(all.length > 0);
			for (byte b : all)
			{
				assertEquals(0, b);              // nothing to hear at the start
			}
		}
	}

	@Test
	public void everySoundIsBundled()
	{
		for (PrayerHoverSoundsConfig.Tone t : PrayerHoverSoundsConfig.Tone.values())
		{
			if (t != PrayerHoverSoundsConfig.Tone.NONE)
			{
				assertNotNull(t.name(), t.file);
				assertNotNull(t.file, PrayerHoverSoundsPlugin.class.getResource(t.file));
			}
		}
	}
